class SwatchAdapter(private val colors: List<Int>) : RecyclerView.Adapter<SwatchAdapter.VH>() {
    class VH(val view: View) : RecyclerView.ViewHolder(view)
    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): VH =
        VH(LayoutInflater.from(parent.context).inflate(R.layout.swatch, parent, false))
    override fun onBindViewHolder(holder: VH, position: Int) {
        holder.view.setBackgroundColor(colors[position])   // caller decides the visuals
    }
    override fun getItemCount() = colors.size
}
